insert into public.questions (id, exam, course_id, section, topic, skill, difficulty, type, content, estimated_seconds, tags, version, is_active) values
  ('sat-math-alg-001', 'sat', 'sat-math', 'Math', 'Algebra', 'Linear equations in one variable', 'easy', 'mcq', '{"id":"sat-math-alg-001","exam":"sat","course":"sat-math","section":"Math","topic":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","type":"mcq","prompt":"If $3x + 7 = 25$, what is the value of $6x - 4$?","choices":[{"id":"A","text":"14"},{"id":"B","text":"26"},{"id":"C","text":"32"},{"id":"D","text":"36"}],"hint":"Solve for $x$ first, or notice that $6x$ is just $2 \\cdot 3x$.","estimatedSeconds":60,"tags":["linear","solving"],"version":1}'::jsonb, 60, array['linear', 'solving']::text[], 1, true),
  ('sat-math-alg-002', 'sat', 'sat-math', 'Math', 'Algebra', 'Linear equations in two variables', 'medium', 'numeric', '{"id":"sat-math-alg-002","exam":"sat","course":"sat-math","section":"Math","topic":"Algebra","skill":"Linear equations in two variables","difficulty":"medium","type":"numeric","prompt":"A line in the $xy$-plane passes through the points $(2, 5)$ and $(6, 17)$. What is the $y$-coordinate of the line''s $y$-intercept?","hint":"Find the slope first, then substitute one of the points into $y = mx + b$.","estimatedSeconds":90,"tags":["slope","intercept"],"version":1}'::jsonb, 90, array['slope', 'intercept']::text[], 1, true),
  ('sat-math-alg-003', 'sat', 'sat-math', 'Math', 'Algebra', 'Systems of two linear equations', 'medium', 'mcq', '{"id":"sat-math-alg-003","exam":"sat","course":"sat-math","section":"Math","topic":"Algebra","skill":"Systems of two linear equations","difficulty":"medium","type":"mcq","prompt":"$$2x + y = 11$$ $$x - y = 1$$ If $(x, y)$ is the solution to the system of equations above, what is the value of $xy$?","choices":[{"id":"A","text":"7"},{"id":"B","text":"12"},{"id":"C","text":"15"},{"id":"D","text":"21"}],"hint":"Adding the two equations eliminates one variable.","estimatedSeconds":90,"tags":["systems","elimination"],"version":1}'::jsonb, 90, array['systems', 'elimination']::text[], 1, true),
  ('sat-math-alg-004', 'sat', 'sat-math', 'Math', 'Algebra', 'Systems of two linear equations', 'hard', 'mcq', '{"id":"sat-math-alg-004","exam":"sat","course":"sat-math","section":"Math","topic":"Algebra","skill":"Systems of two linear equations","difficulty":"hard","type":"mcq","prompt":"$$kx + 3y = 12$$ $$4x + 6y = 9$$ In the system of equations above, $k$ is a constant. For what value of $k$ does the system have no solution?","choices":[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"6"},{"id":"D","text":"8"}],"hint":"No solution means the lines are parallel: what must be true about the ratios of the coefficients?","estimatedSeconds":110,"tags":["systems","parallel lines","no solution"],"version":1}'::jsonb, 110, array['systems', 'parallel lines', 'no solution']::text[], 1, true),
  ('sat-math-alg-005', 'sat', 'sat-math', 'Math', 'Algebra', 'Linear inequalities in one or two variables', 'easy', 'mcq', '{"id":"sat-math-alg-005","exam":"sat","course":"sat-math","section":"Math","topic":"Algebra","skill":"Linear inequalities in one or two variables","difficulty":"easy","type":"mcq","prompt":"A climbing gym charges a one-time sign-up fee of $\\$40$ plus $\\$25$ per month. Which inequality represents the numbers of months, $m$, for which a member''s total cost is at most $\\$340$?","choices":[{"id":"A","text":"$25 + 40m \\le 340$"},{"id":"B","text":"$40 + 25m \\ge 340$"},{"id":"C","text":"$65m \\le 340$"},{"id":"D","text":"$40 + 25m \\le 340$"}],"estimatedSeconds":60,"tags":["modeling","inequalities"],"version":1}'::jsonb, 60, array['modeling', 'inequalities']::text[], 1, true),
  ('sat-math-adv-001', 'sat', 'sat-math', 'Math', 'Advanced Math', 'Equivalent expressions', 'medium', 'mcq', '{"id":"sat-math-adv-001","exam":"sat","course":"sat-math","section":"Math","topic":"Advanced Math","skill":"Equivalent expressions","difficulty":"medium","type":"mcq","prompt":"Which of the following is equivalent to $(x + 5)^2 - (x - 5)^2$?","choices":[{"id":"A","text":"$0$"},{"id":"B","text":"$10x$"},{"id":"C","text":"$20x$"},{"id":"D","text":"$50$"}],"hint":"Try the difference of squares pattern $a^2 - b^2 = (a+b)(a-b)$.","estimatedSeconds":80,"tags":["polynomials","difference of squares"],"version":1}'::jsonb, 80, array['polynomials', 'difference of squares']::text[], 1, true),
  ('sat-math-adv-002', 'sat', 'sat-math', 'Math', 'Advanced Math', 'Nonlinear equations in one variable', 'medium', 'numeric', '{"id":"sat-math-adv-002","exam":"sat","course":"sat-math","section":"Math","topic":"Advanced Math","skill":"Nonlinear equations in one variable","difficulty":"medium","type":"numeric","prompt":"What is the positive difference between the two solutions of $x^2 - 8x + 15 = 0$?","hint":"Look for two numbers that multiply to 15 and add to $-8$.","estimatedSeconds":75,"tags":["quadratics","factoring"],"version":1}'::jsonb, 75, array['quadratics', 'factoring']::text[], 1, true),
  ('sat-math-adv-003', 'sat', 'sat-math', 'Math', 'Advanced Math', 'Nonlinear functions', 'hard', 'mcq', '{"id":"sat-math-adv-003","exam":"sat","course":"sat-math","section":"Math","topic":"Advanced Math","skill":"Nonlinear functions","difficulty":"hard","type":"mcq","prompt":"The function $f$ is defined by $f(x) = a(x - 3)^2 + 2$, where $a$ is a constant. If $f(5) = 14$, what is the value of $f(0)$?","choices":[{"id":"A","text":"27"},{"id":"B","text":"33.5"},{"id":"C","text":"56"},{"id":"D","text":"29"}],"hint":"Use the given point to solve for $a$ before evaluating $f(0)$.","estimatedSeconds":100,"tags":["vertex form","function evaluation"],"version":1}'::jsonb, 100, array['vertex form', 'function evaluation']::text[], 1, true),
  ('sat-math-adv-004', 'sat', 'sat-math', 'Math', 'Advanced Math', 'Nonlinear functions', 'medium', 'mcq', '{"id":"sat-math-adv-004","exam":"sat","course":"sat-math","section":"Math","topic":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","type":"mcq","prompt":"A lab culture starts with 500 bacteria, and the number of bacteria doubles every 3 hours. Which function gives the number of bacteria, $P(t)$, after $t$ hours?","choices":[{"id":"A","text":"$P(t) = 500(2)^{3t}$"},{"id":"B","text":"$P(t) = 500(2)^{t/3}$"},{"id":"C","text":"$P(t) = 500(3)^{t/2}$"},{"id":"D","text":"$P(t) = 500 + 2^{t/3}$"}],"estimatedSeconds":75,"tags":["exponential growth","modeling"],"version":1}'::jsonb, 75, array['exponential growth', 'modeling']::text[], 1, true),
  ('sat-math-adv-005', 'sat', 'sat-math', 'Math', 'Advanced Math', 'Nonlinear equations in one variable', 'hard', 'numeric', '{"id":"sat-math-adv-005","exam":"sat","course":"sat-math","section":"Math","topic":"Advanced Math","skill":"Nonlinear equations in one variable","difficulty":"hard","type":"numeric","prompt":"If $\\dfrac{x^2 - 9}{x - 3} = 10$, what is the value of $x$?","hint":"The numerator is a difference of squares.","estimatedSeconds":90,"tags":["rational expressions"],"version":1}'::jsonb, 90, array['rational expressions']::text[], 1, true),
  ('sat-math-psd-001', 'sat', 'sat-math', 'Math', 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportional relationships', 'easy', 'mcq', '{"id":"sat-math-psd-001","exam":"sat","course":"sat-math","section":"Math","topic":"Problem-Solving and Data Analysis","skill":"Ratios, rates, and proportional relationships","difficulty":"easy","type":"mcq","prompt":"A car travels 168 miles using 6 gallons of gasoline. At the same rate, how many gallons will the car use to travel 252 miles?","choices":[{"id":"A","text":"8"},{"id":"B","text":"9"},{"id":"C","text":"10"},{"id":"D","text":"12"}],"estimatedSeconds":60,"tags":["unit rate"],"version":1}'::jsonb, 60, array['unit rate']::text[], 1, true),
  ('sat-math-psd-002', 'sat', 'sat-math', 'Math', 'Problem-Solving and Data Analysis', 'Percentages', 'medium', 'numeric', '{"id":"sat-math-psd-002","exam":"sat","course":"sat-math","section":"Math","topic":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"medium","type":"numeric","prompt":"The price of a jacket was $\\$80$. The price was increased by $25\\%$, and then the new price was decreased by $20\\%$. What is the final price of the jacket, in dollars?","hint":"Apply each change as a multiplier: an increase of 25% multiplies by 1.25.","estimatedSeconds":75,"tags":["percent change","multipliers"],"version":1}'::jsonb, 75, array['percent change', 'multipliers']::text[], 1, true),
  ('sat-math-psd-003', 'sat', 'sat-math', 'Math', 'Problem-Solving and Data Analysis', 'Probability and conditional probability', 'medium', 'mcq', '{"id":"sat-math-psd-003","exam":"sat","course":"sat-math","section":"Math","topic":"Problem-Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"medium","type":"mcq","prompt":"The table shows the club choices of 80 students in grades 10 and 11. If a student in the debate club is selected at random, what is the probability that the student is in grade 11?","figure":{"kind":"table","caption":"Club membership by grade","columns":["","Robotics","Debate","Total"],"rows":[["Grade 10","18","12","30"],["Grade 11","22","28","50"],["Total","40","40","80"]]},"choices":[{"id":"A","text":"$\\frac{7}{20}$"},{"id":"B","text":"$\\frac{14}{25}$"},{"id":"C","text":"$\\frac{3}{10}$"},{"id":"D","text":"$\\frac{7}{10}$"}],"hint":"The phrase \"a student in the debate club\" tells you which total to use as the denominator.","estimatedSeconds":80,"tags":["two-way table","conditional probability"],"version":1}'::jsonb, 80, array['two-way table', 'conditional probability']::text[], 1, true),
  ('sat-math-psd-004', 'sat', 'sat-math', 'Math', 'Problem-Solving and Data Analysis', 'Two-variable data: models and scatterplots', 'medium', 'mcq', '{"id":"sat-math-psd-004","exam":"sat","course":"sat-math","section":"Math","topic":"Problem-Solving and Data Analysis","skill":"Two-variable data: models and scatterplots","difficulty":"medium","type":"mcq","prompt":"The scatterplot shows the number of hours eight students spent preparing for a quiz and their quiz scores. Which of the following is closest to the slope of a line of best fit for the data?","figure":{"kind":"chart","chartType":"scatter","title":"Preparation time and quiz score","xLabel":"Hours of preparation","yLabel":"Quiz score","data":[{"x":1,"y":52},{"x":2,"y":55},{"x":3,"y":61},{"x":4,"y":63},{"x":5,"y":68},{"x":6,"y":71},{"x":7,"y":75},{"x":8,"y":79}]},"choices":[{"id":"A","text":"0.26"},{"id":"B","text":"3.9"},{"id":"C","text":"13.5"},{"id":"D","text":"52"}],"estimatedSeconds":80,"tags":["scatterplot","line of best fit","slope"],"version":1}'::jsonb, 80, array['scatterplot', 'line of best fit', 'slope']::text[], 1, true),
  ('sat-math-geo-001', 'sat', 'sat-math', 'Math', 'Geometry and Trigonometry', 'Right triangles and trigonometry', 'medium', 'mcq', '{"id":"sat-math-geo-001","exam":"sat","course":"sat-math","section":"Math","topic":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"medium","type":"mcq","prompt":"In right triangle $ABC$ shown, angle $C$ is a right angle, $AC = 9$, and $BC = 12$. What is the value of $\\sin A$?","figure":{"kind":"image","src":"/figures/right-triangle-abc.svg","alt":"Right triangle ABC with the right angle at C. Side AC is 9 units and side BC is 12 units. The hypotenuse AB is not labeled.","width":320,"height":220},"choices":[{"id":"A","text":"$\\frac{3}{5}$"},{"id":"B","text":"$\\frac{3}{4}$"},{"id":"C","text":"$\\frac{4}{5}$"},{"id":"D","text":"$\\frac{4}{3}$"}],"hint":"SOH: sine is opposite over hypotenuse. Find the hypotenuse with the Pythagorean theorem.","estimatedSeconds":85,"tags":["SOH CAH TOA","Pythagorean theorem"],"version":1}'::jsonb, 85, array['SOH CAH TOA', 'Pythagorean theorem']::text[], 1, true),
  ('sat-math-geo-002', 'sat', 'sat-math', 'Math', 'Geometry and Trigonometry', 'Circles', 'hard', 'numeric', '{"id":"sat-math-geo-002","exam":"sat","course":"sat-math","section":"Math","topic":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","type":"numeric","prompt":"A circle in the $xy$-plane has the equation $x^2 + y^2 - 6x + 8y = 0$. What is the radius of the circle?","hint":"Complete the square for the $x$ terms and the $y$ terms separately.","estimatedSeconds":110,"tags":["completing the square","circle equation"],"version":1}'::jsonb, 110, array['completing the square', 'circle equation']::text[], 1, true),
  ('sat-math-geo-003', 'sat', 'sat-math', 'Math', 'Geometry and Trigonometry', 'Area and volume', 'easy', 'mcq', '{"id":"sat-math-geo-003","exam":"sat","course":"sat-math","section":"Math","topic":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"easy","type":"mcq","prompt":"A rectangular box has a length of 6 centimeters, a width of 4 centimeters, and a volume of 168 cubic centimeters. What is the height of the box, in centimeters?","choices":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"estimatedSeconds":50,"tags":["volume","rectangular prism"],"version":1}'::jsonb, 50, array['volume', 'rectangular prism']::text[], 1, true),
  ('sat-math-geo-004', 'sat', 'sat-math', 'Math', 'Geometry and Trigonometry', 'Lines, angles, and triangles', 'medium', 'mcq', '{"id":"sat-math-geo-004","exam":"sat","course":"sat-math","section":"Math","topic":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"medium","type":"mcq","prompt":"The measures of the three angles of a triangle are $x^\\circ$, $2x^\\circ$, and $(3x - 30)^\\circ$. What is the measure, in degrees, of the largest angle of the triangle?","choices":[{"id":"A","text":"35"},{"id":"B","text":"70"},{"id":"C","text":"105"},{"id":"D","text":"75"}],"estimatedSeconds":75,"tags":["triangle angle sum"],"version":1}'::jsonb, 75, array['triangle angle sum']::text[], 1, true),
  ('sat-rw-wic-001', 'sat', 'sat-rw', 'Reading and Writing', 'Craft and Structure', 'Words in context', 'medium', 'mcq', '{"id":"sat-rw-wic-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Craft and Structure","skill":"Words in context","difficulty":"medium","type":"mcq","passage":{"text":"Marine biologist Ayana Brooks noted that the coral colony''s recovery after the heat wave was far from ______: although some branches regrew within months, others remained bleached for years, and a few never recovered at all."},"prompt":"Which choice completes the text with the most logical and precise word?","choices":[{"id":"A","text":"uniform"},{"id":"B","text":"sudden"},{"id":"C","text":"invisible"},{"id":"D","text":"permanent"}],"hint":"Read what comes after the colon: it explains what the recovery was \"far from.\"","estimatedSeconds":70,"tags":["vocabulary","context clues"],"version":1}'::jsonb, 70, array['vocabulary', 'context clues']::text[], 1, true),
  ('sat-rw-wic-002', 'sat', 'sat-rw', 'Reading and Writing', 'Craft and Structure', 'Words in context', 'hard', 'mcq', '{"id":"sat-rw-wic-002","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Craft and Structure","skill":"Words in context","difficulty":"hard","type":"mcq","passage":{"text":"The novelist''s early reviewers were ______ in their praise; even critics who usually found fault with debut works described her prose as assured and inventive."},"prompt":"Which choice completes the text with the most logical and precise word?","choices":[{"id":"A","text":"tepid"},{"id":"B","text":"ambivalent"},{"id":"C","text":"unstinting"},{"id":"D","text":"premature"}],"estimatedSeconds":75,"tags":["vocabulary","tone"],"version":1}'::jsonb, 75, array['vocabulary', 'tone']::text[], 1, true),
  ('sat-rw-wic-003', 'sat', 'sat-rw', 'Reading and Writing', 'Craft and Structure', 'Words in context', 'easy', 'mcq', '{"id":"sat-rw-wic-003","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Craft and Structure","skill":"Words in context","difficulty":"easy","type":"mcq","passage":{"text":"Despite the storm''s intensity, the old lighthouse remained ______; the next morning, keepers found its stone walls without a single new crack."},"prompt":"Which choice completes the text with the most logical and precise word?","choices":[{"id":"A","text":"fragile"},{"id":"B","text":"intact"},{"id":"C","text":"abandoned"},{"id":"D","text":"illuminated"}],"estimatedSeconds":55,"tags":["vocabulary"],"version":1}'::jsonb, 55, array['vocabulary']::text[], 1, true),
  ('sat-rw-tsp-001', 'sat', 'sat-rw', 'Reading and Writing', 'Craft and Structure', 'Text structure and purpose', 'medium', 'mcq', '{"id":"sat-rw-tsp-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Craft and Structure","skill":"Text structure and purpose","difficulty":"medium","type":"mcq","passage":{"text":"In many cities, neighborhoods with few trees can be several degrees hotter on summer afternoons than nearby areas with dense tree cover. To address this, the fictional city of Fairhaven planted 12,000 street trees between 2015 and 2022, prioritizing the blocks with the highest recorded surface temperatures. Early measurements suggest that those blocks have cooled more than blocks that received fewer trees, though officials caution that the young trees will not reach full size for another decade."},"prompt":"Which choice best describes the overall structure of the text?","choices":[{"id":"A","text":"It presents two competing theories about urban heat and argues that one is correct."},{"id":"B","text":"It describes a historical event and traces its long-term consequences."},{"id":"C","text":"It summarizes a scientific debate and calls for more research."},{"id":"D","text":"It identifies a problem, describes a response to it, and reports preliminary results of that response."}],"estimatedSeconds":75,"tags":["structure","purpose"],"version":1}'::jsonb, 75, array['structure', 'purpose']::text[], 1, true),
  ('sat-rw-ctc-001', 'sat', 'sat-rw', 'Reading and Writing', 'Craft and Structure', 'Cross-text connections', 'hard', 'mcq', '{"id":"sat-rw-ctc-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","type":"mcq","passage":{"title":"Text 1 and Text 2","text":"Text 1\nFor much of the twentieth century, many paleontologists assumed that giant sauropod dinosaurs spent much of their lives in lakes and swamps, where water was thought to help support their enormous bodies.\n\nText 2\nAnalyses of sauropod limb bones show columnlike legs and compact feet suited to bearing weight on land. Fossilized trackways add further evidence, recording herds of sauropods walking across firm ground. Most researchers now conclude that sauropods were primarily land dwellers."},"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the assumption described in Text 1?","choices":[{"id":"A","text":"By agreeing with it but noting that fossilized trackways are rare"},{"id":"B","text":"By arguing that physical evidence from bones and trackways undermines it"},{"id":"C","text":"By claiming that sauropods were smaller than earlier researchers believed"},{"id":"D","text":"By suggesting that it applied only to young sauropods"}],"estimatedSeconds":90,"tags":["paired texts","evidence"],"version":1}'::jsonb, 90, array['paired texts', 'evidence']::text[], 1, true),
  ('sat-rw-cid-001', 'sat', 'sat-rw', 'Reading and Writing', 'Information and Ideas', 'Central ideas and details', 'medium', 'mcq', '{"id":"sat-rw-cid-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Information and Ideas","skill":"Central ideas and details","difficulty":"medium","type":"mcq","passage":{"text":"Clark''s nutcrackers, birds of western North American mountains, bury thousands of pine seeds in scattered caches each fall and retrieve many of them months later, sometimes from beneath snow. In laboratory and field studies, researchers found that when nearby objects such as stones were moved, the birds searched in the spot that matched the objects'' new positions rather than the true location of the seeds. The findings indicate that the birds remember where caches are relative to landmarks."},"prompt":"Which choice best states the main idea of the text?","choices":[{"id":"A","text":"Clark''s nutcrackers bury seeds beneath snow to hide them from other animals."},{"id":"B","text":"Clark''s nutcrackers rely mainly on their sense of smell to find stored seeds."},{"id":"C","text":"Research suggests that Clark''s nutcrackers find their seed caches by remembering the caches'' positions relative to landmarks."},{"id":"D","text":"Clark''s nutcrackers store fewer seeds than most other seed-caching birds."}],"estimatedSeconds":80,"tags":["main idea","science passage"],"version":1}'::jsonb, 80, array['main idea', 'science passage']::text[], 1, true),
  ('sat-rw-coe-001', 'sat', 'sat-rw', 'Reading and Writing', 'Information and Ideas', 'Command of evidence: quantitative', 'hard', 'mcq', '{"id":"sat-rw-coe-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Information and Ideas","skill":"Command of evidence: quantitative","difficulty":"hard","type":"mcq","passage":{"text":"A student studying a community garden compared plots watered by drip irrigation with plots watered by hand. The student claims that the advantage of drip irrigation over hand watering was greatest during the hottest season of the year, summer."},"figure":{"kind":"table","caption":"Average weekly vegetable yield per plot (kilograms)","columns":["Season","Drip irrigation","Hand watering"],"rows":[["Spring","4.2","3.9"],["Summer","6.8","5.1"],["Fall","3.5","3.4"]]},"prompt":"Which choice most effectively uses data from the table to support the student''s claim?","choices":[{"id":"A","text":"Drip-irrigated plots produced more in summer (6.8 kilograms) than in spring (4.2 kilograms)."},{"id":"B","text":"In fall, both drip-irrigated and hand-watered plots averaged less than 4 kilograms per week."},{"id":"C","text":"In spring, hand-watered plots averaged 3.9 kilograms per week."},{"id":"D","text":"In summer, drip-irrigated plots averaged 1.7 kilograms more per week than hand-watered plots, a larger gap than in spring (0.3) or fall (0.1)."}],"hint":"The claim is about the gap between the two methods, not about either method alone.","estimatedSeconds":95,"tags":["data","table","claims"],"version":1}'::jsonb, 95, array['data', 'table', 'claims']::text[], 1, true),
  ('sat-rw-coe-002', 'sat', 'sat-rw', 'Reading and Writing', 'Information and Ideas', 'Command of evidence: textual', 'medium', 'mcq', '{"id":"sat-rw-coe-002","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Information and Ideas","skill":"Command of evidence: textual","difficulty":"medium","type":"mcq","passage":{"text":"In the original short story \"The Lamplighter''s Daughter,\" the narrator portrays Mara as a person who finds comfort in routine."},"prompt":"Which quotation from the story most effectively illustrates the claim?","choices":[{"id":"A","text":"\"Mara had never seen the ocean, though she often dreamed of it.\""},{"id":"B","text":"\"Every evening at six, Mara set out the same chipped blue cup, and only then did her shoulders loosen.\""},{"id":"C","text":"\"The town council argued for hours about the rising price of lamp oil.\""},{"id":"D","text":"\"Her brother left for the city one spring morning without saying goodbye.\""}],"estimatedSeconds":70,"tags":["literary evidence","characterization"],"version":1}'::jsonb, 70, array['literary evidence', 'characterization']::text[], 1, true),
  ('sat-rw-inf-001', 'sat', 'sat-rw', 'Reading and Writing', 'Information and Ideas', 'Inferences', 'hard', 'mcq', '{"id":"sat-rw-inf-001","exam":"sat","course":"sat-rw","section":"Reading and Writing","topic":"Information and Ideas","skill":"Inferences","difficulty":"hard","type":"mcq","passage":{"text":"Archaeologists excavating a hilltop settlement found pottery fragments made from a type of clay that does not occur naturally within 200 kilometers of the site. The fragments'' painted designs, however, closely match those on other ceramics known to have been produced at the settlement. These findings suggest that ______"},"prompt":"Which choice most logically completes the text?","choices":[{"id":"A","text":"the settlement''s potters were unfamiliar with local decorative styles."},{"id":"B","text":"the clay near the settlement was too soft to hold painted designs."},{"id":"C","text":"the settlement was abandoned before pottery became common in the region."},{"id":"D","text":"the settlement''s potters obtained clay from a distant source, possibly through trade."}],"estimatedSeconds":85,"tags":["inference","archaeology"],"version":1}'::jsonb, 85, array['inference', 'archaeology']::text[], 1, true),
