  ('apush-p2-001', 'ap', 'ap-us-history', 'Period 2: 1607-1754', 'Colonial labor systems', 'Causation', 'medium', 'mcq', '{"id":"apush-p2-001","exam":"ap","course":"ap-us-history","section":"Period 2: 1607-1754","topic":"Colonial labor systems","skill":"Causation","difficulty":"medium","type":"mcq","passage":{"title":"Secondary source summary","text":"In the Chesapeake colonies of the 1600s, tobacco cultivation demanded large amounts of labor. Planters initially relied heavily on indentured servants from England. By the early 1700s, however, enslaved Africans made up a growing share of the region''s unfree labor force.","source":"Original summary written for practice"},"prompt":"Which of the following most directly contributed to the shift described in the passage?","choices":[{"id":"A","text":"The invention of the cotton gin"},{"id":"B","text":"The religious revivals of the First Great Awakening"},{"id":"C","text":"A decline in English migrants willing to become servants, along with planters'' fears of armed former servants after Bacon''s Rebellion"},{"id":"D","text":"The abolition of the transatlantic slave trade by Congress"}],"estimatedSeconds":75,"tags":["Chesapeake","indentured servitude","slavery","Bacon''s Rebellion"],"version":1}'::jsonb, 75, array['Chesapeake', 'indentured servitude', 'slavery', 'Bacon''s Rebellion']::text[], 1, true),
