  ('apush-p4-001', 'ap', 'ap-us-history', 'Period 4: 1800-1848', 'The Market Revolution', 'Continuity and change', 'medium', 'mcq', '{"id":"apush-p4-001","exam":"ap","course":"ap-us-history","section":"Period 4: 1800-1848","topic":"The Market Revolution","skill":"Continuity and change","difficulty":"medium","type":"mcq","passage":{"title":"Secondary source summary","text":"Completed in 1825, the Erie Canal connected the Hudson River to Lake Erie. Shipping costs between Buffalo and New York City fell dramatically, and the time needed to move goods between the two cities dropped from weeks to days.","source":"Original summary written for practice"},"prompt":"Which of the following was a significant effect of the development described in the passage?","choices":[{"id":"A","text":"Stronger economic ties between the Northeast and the agricultural Midwest"},{"id":"B","text":"The end of steamboat traffic on major American rivers"},{"id":"C","text":"A decline in New York City''s importance as a port"},{"id":"D","text":"Closer economic ties between the Midwest and the South than between the Midwest and the Northeast"}],"estimatedSeconds":60,"tags":["Erie Canal","transportation revolution"],"version":1}'::jsonb, 60, array['Erie Canal', 'transportation revolution']::text[], 1, true),
  ('apush-p5-001', 'ap', 'ap-us-history', 'Period 5: 1844-1877', 'Sectional conflict', 'Causation', 'medium', 'mcq', '{"id":"apush-p5-001","exam":"ap","course":"ap-us-history","section":"Period 5: 1844-1877","topic":"Sectional conflict","skill":"Causation","difficulty":"medium","type":"mcq","passage":{"title":"Secondary source summary","text":"As part of the Compromise of 1850, Congress passed a strengthened Fugitive Slave Act. It required officials and citizens in free states to assist in capturing people who had escaped slavery, denied accused individuals a jury trial, and paid commissioners more for ruling in favor of claimants.","source":"Original summary written for practice"},"prompt":"The law described in the passage most directly led to which of the following?","choices":[{"id":"A","text":"The immediate secession of southern states in 1850"},{"id":"B","text":"The collapse of the Republican Party"},{"id":"C","text":"Increased resistance in the North, including personal liberty laws and support for the Underground Railroad"},{"id":"D","text":"A national agreement to end the expansion of slavery"}],"estimatedSeconds":70,"tags":["Compromise of 1850","Fugitive Slave Act","abolition"],"version":1}'::jsonb, 70, array['Compromise of 1850', 'Fugitive Slave Act', 'abolition']::text[], 1, true),
  ('apush-p6-001', 'ap', 'ap-us-history', 'Period 6: 1865-1898', 'Government and the economy in the Gilded Age', 'Contextualization', 'medium', 'mcq', '{"id":"apush-p6-001","exam":"ap","course":"ap-us-history","section":"Period 6: 1865-1898","topic":"Government and the economy in the Gilded Age","skill":"Contextualization","difficulty":"medium","type":"mcq","prompt":"Which of the following best describes the purpose of the Interstate Commerce Act of 1887?","choices":[{"id":"A","text":"To break up the Standard Oil Company"},{"id":"B","text":"To establish a federal income tax"},{"id":"C","text":"To restrict immigration from China"},{"id":"D","text":"To regulate railroads and require that their rates be reasonable and just"}],"estimatedSeconds":55,"tags":["regulation","railroads","Populism"],"version":1}'::jsonb, 55, array['regulation', 'railroads', 'Populism']::text[], 1, true),
  ('apush-p7-001', 'ap', 'ap-us-history', 'Period 7: 1890-1945', 'The Progressive Era', 'Causation', 'easy', 'mcq', '{"id":"apush-p7-001","exam":"ap","course":"ap-us-history","section":"Period 7: 1890-1945","topic":"The Progressive Era","skill":"Causation","difficulty":"easy","type":"mcq","prompt":"Upton Sinclair''s novel The Jungle (1906), which exposed unsanitary conditions in Chicago meatpacking plants, contributed most directly to which of the following?","choices":[{"id":"A","text":"The Sherman Antitrust Act"},{"id":"B","text":"The Meat Inspection Act and the Pure Food and Drug Act"},{"id":"C","text":"The Nineteenth Amendment"},{"id":"D","text":"The Federal Reserve Act"}],"estimatedSeconds":45,"tags":["muckrakers","Progressivism","consumer protection"],"version":1}'::jsonb, 45, array['muckrakers', 'Progressivism', 'consumer protection']::text[], 1, true),
  ('apush-p7-002', 'ap', 'ap-us-history', 'Period 7: 1890-1945', 'The New Deal', 'Comparison', 'medium', 'mcq', '{"id":"apush-p7-002","exam":"ap","course":"ap-us-history","section":"Period 7: 1890-1945","topic":"The New Deal","skill":"Comparison","difficulty":"medium","type":"mcq","passage":{"title":"Secondary source summary","text":"The Social Security Act of 1935 created a federal system of old-age pensions funded by payroll taxes, along with unemployment insurance administered jointly with the states and aid for dependent children.","source":"Original summary written for practice"},"prompt":"The law described in the passage best reflects which broader change in the 1930s?","choices":[{"id":"A","text":"A return to the laissez-faire policies of the 1920s"},{"id":"B","text":"A sharp reduction in federal spending to balance the budget"},{"id":"C","text":"An expanded federal role in providing economic security to individuals"},{"id":"D","text":"The transfer of responsibility for welfare from the federal government to private charities"}],"estimatedSeconds":55,"tags":["New Deal","welfare state"],"version":1}'::jsonb, 55, array['New Deal', 'welfare state']::text[], 1, true),
  ('apush-p8-001', 'ap', 'ap-us-history', 'Period 8: 1945-1980', 'The early Cold War', 'Contextualization', 'easy', 'mcq', '{"id":"apush-p8-001","exam":"ap","course":"ap-us-history","section":"Period 8: 1945-1980","topic":"The early Cold War","skill":"Contextualization","difficulty":"easy","type":"mcq","prompt":"The Marshall Plan (1948) was primarily intended to","choices":[{"id":"A","text":"rebuild Western European economies in order to reduce the appeal of communism"},{"id":"B","text":"create a military alliance among the United States and Western European nations"},{"id":"C","text":"provide military assistance to South Korea"},{"id":"D","text":"collect war reparations from Germany"}],"estimatedSeconds":40,"tags":["containment","Cold War"],"version":1}'::jsonb, 40, array['containment', 'Cold War']::text[], 1, true),
  ('apush-p8-002', 'ap', 'ap-us-history', 'Period 8: 1945-1980', 'The civil rights movement', 'Causation', 'easy', 'mcq', '{"id":"apush-p8-002","exam":"ap","course":"ap-us-history","section":"Period 8: 1945-1980","topic":"The civil rights movement","skill":"Causation","difficulty":"easy","type":"mcq","prompt":"In Brown v. Board of Education of Topeka (1954), the Supreme Court ruled that","choices":[{"id":"A","text":"the doctrine of \"separate but equal\" was constitutional in public facilities"},{"id":"B","text":"school districts must use busing to integrate schools"},{"id":"C","text":"suspects must be informed of their rights before police questioning"},{"id":"D","text":"state-mandated racial segregation of public schools is unconstitutional"}],"estimatedSeconds":40,"tags":["Supreme Court","segregation"],"version":1}'::jsonb, 40, array['Supreme Court', 'segregation']::text[], 1, true),
  ('apush-p9-001', 'ap', 'ap-us-history', 'Period 9: 1980-Present', 'The conservative resurgence', 'Comparison', 'medium', 'mcq', '{"id":"apush-p9-001","exam":"ap","course":"ap-us-history","section":"Period 9: 1980-Present","topic":"The conservative resurgence","skill":"Comparison","difficulty":"medium","type":"mcq","prompt":"Which of the following developments of the 1980s most clearly reflected the rise of political conservatism?","choices":[{"id":"A","text":"The expansion of Great Society programs"},{"id":"B","text":"The creation of the Environmental Protection Agency"},{"id":"C","text":"Federal income tax cuts and efforts to deregulate industries"},{"id":"D","text":"The passage of the Civil Rights Act"}],"estimatedSeconds":45,"tags":["Reagan","conservatism"],"version":1}'::jsonb, 45, array['Reagan', 'conservatism']::text[], 1, true),
  ('ap-lang-p1-001', 'ap', 'ap-english-language', 'Rhetorical Situation', 'Purpose', 'Identifying the writer''s purpose', 'medium', 'mcq', '{"id":"ap-lang-p1-001","exam":"ap","course":"ap-english-language","section":"Rhetorical Situation","topic":"Purpose","skill":"Identifying the writer''s purpose","difficulty":"medium","type":"mcq","passage":{"title":"Passage 1 (original op-ed)","text":"When my town proposed closing its branch library to save money, the arguments seemed reasonable at first. Fewer people borrow books than a decade ago; most residents carry the internet in their pockets. But on a Tuesday afternoon I counted forty-three people in a building that is supposedly obsolete. A retired machinist was learning to file his taxes online. Two high school students were printing college applications because neither had a printer at home. A mother read picture books to her twins while she waited for a call about a job interview. None of them came for a book, and all of them came for the library. The question is not whether we still need places that lend paper; it is whether we still need places that lend help, quietly and without asking anything in return. I suspect the answer is the same as it was a century ago.","source":"Original passage written for practice"},"prompt":"The writer''s primary purpose in the passage is to","choices":[{"id":"A","text":"criticize residents for no longer borrowing books"},{"id":"B","text":"argue that the library remains valuable by redefining what it provides"},{"id":"C","text":"explain the history of public libraries in the writer''s town"},{"id":"D","text":"propose a new way to fund the branch library"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p1-002', 'ap', 'ap-english-language', 'Claims and Evidence', 'Evidence', 'Function of evidence', 'medium', 'mcq', '{"id":"ap-lang-p1-002","exam":"ap","course":"ap-english-language","section":"Claims and Evidence","topic":"Evidence","skill":"Function of evidence","difficulty":"medium","type":"mcq","passage":{"title":"Passage 1 (original op-ed)","text":"When my town proposed closing its branch library to save money, the arguments seemed reasonable at first. Fewer people borrow books than a decade ago; most residents carry the internet in their pockets. But on a Tuesday afternoon I counted forty-three people in a building that is supposedly obsolete. A retired machinist was learning to file his taxes online. Two high school students were printing college applications because neither had a printer at home. A mother read picture books to her twins while she waited for a call about a job interview. None of them came for a book, and all of them came for the library. The question is not whether we still need places that lend paper; it is whether we still need places that lend help, quietly and without asking anything in return. I suspect the answer is the same as it was a century ago.","source":"Original passage written for practice"},"prompt":"The examples of the machinist, the students, and the mother primarily serve to","choices":[{"id":"A","text":"demonstrate statistical trends in library use"},{"id":"B","text":"illustrate that the library''s collection is outdated"},{"id":"C","text":"provide concrete evidence that challenges the assumption that the library is obsolete"},{"id":"D","text":"suggest that the library should extend its hours"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p1-003', 'ap', 'ap-english-language', 'Style', 'Sentence-level choices', 'Syntax and parallelism', 'hard', 'mcq', '{"id":"ap-lang-p1-003","exam":"ap","course":"ap-english-language","section":"Style","topic":"Sentence-level choices","skill":"Syntax and parallelism","difficulty":"hard","type":"mcq","passage":{"title":"Passage 1 (original op-ed)","text":"When my town proposed closing its branch library to save money, the arguments seemed reasonable at first. Fewer people borrow books than a decade ago; most residents carry the internet in their pockets. But on a Tuesday afternoon I counted forty-three people in a building that is supposedly obsolete. A retired machinist was learning to file his taxes online. Two high school students were printing college applications because neither had a printer at home. A mother read picture books to her twins while she waited for a call about a job interview. None of them came for a book, and all of them came for the library. The question is not whether we still need places that lend paper; it is whether we still need places that lend help, quietly and without asking anything in return. I suspect the answer is the same as it was a century ago.","source":"Original passage written for practice"},"prompt":"The sentence \"None of them came for a book, and all of them came for the library\" primarily uses","choices":[{"id":"A","text":"an appeal to authority to support the writer''s claim"},{"id":"B","text":"hyperbole to exaggerate the number of visitors"},{"id":"C","text":"an extended metaphor comparing the library to a home"},{"id":"D","text":"parallel structure and contrast to distinguish books from the services a library offers"}],"estimatedSeconds":80,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 80, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p2-001', 'ap', 'ap-english-language', 'Rhetorical Situation', 'Audience', 'Rhetorical choices and audience', 'medium', 'mcq', '{"id":"ap-lang-p2-001","exam":"ap","course":"ap-english-language","section":"Rhetorical Situation","topic":"Audience","skill":"Rhetorical choices and audience","difficulty":"medium","type":"mcq","passage":{"title":"Passage 2 (original commencement speech excerpt)","text":"Graduates, you have been told for years that you can be anything. That is not quite true, and I think you deserve the truth on a day like this. You cannot be anything. You can, however, become something, and becoming is slower, stranger, and far more interesting than being. Becoming requires you to be bad at things in public. It requires you to ask questions that reveal exactly what you do not know. The people you admire most did not skip this stage; they simply refused to let it embarrass them out of the room.","source":"Original passage written for practice"},"prompt":"The speaker most likely begins by contradicting a familiar statement in order to","choices":[{"id":"A","text":"capture the audience''s attention and establish a candid tone"},{"id":"B","text":"criticize the graduates'' former teachers"},{"id":"C","text":"signal that the speech will be humorous throughout"},{"id":"D","text":"list the speaker''s professional credentials"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p2-002', 'ap', 'ap-english-language', 'Reasoning and Organization', 'Line of reasoning', 'Developing a claim through distinction', 'medium', 'mcq', '{"id":"ap-lang-p2-002","exam":"ap","course":"ap-english-language","section":"Reasoning and Organization","topic":"Line of reasoning","skill":"Developing a claim through distinction","difficulty":"medium","type":"mcq","passage":{"title":"Passage 2 (original commencement speech excerpt)","text":"Graduates, you have been told for years that you can be anything. That is not quite true, and I think you deserve the truth on a day like this. You cannot be anything. You can, however, become something, and becoming is slower, stranger, and far more interesting than being. Becoming requires you to be bad at things in public. It requires you to ask questions that reveal exactly what you do not know. The people you admire most did not skip this stage; they simply refused to let it embarrass them out of the room.","source":"Original passage written for practice"},"prompt":"The distinction between \"being\" and \"becoming\" functions mainly to","choices":[{"id":"A","text":"contrast two specific careers the graduates might pursue"},{"id":"B","text":"argue that ambition is unnecessary for success"},{"id":"C","text":"reframe achievement as a gradual process that includes public failure"},{"id":"D","text":"dismiss the people the graduates admire"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p2-003', 'ap', 'ap-english-language', 'Style', 'Figurative language', 'Interpreting figurative language', 'hard', 'mcq', '{"id":"ap-lang-p2-003","exam":"ap","course":"ap-english-language","section":"Style","topic":"Figurative language","skill":"Interpreting figurative language","difficulty":"hard","type":"mcq","passage":{"title":"Passage 2 (original commencement speech excerpt)","text":"Graduates, you have been told for years that you can be anything. That is not quite true, and I think you deserve the truth on a day like this. You cannot be anything. You can, however, become something, and becoming is slower, stranger, and far more interesting than being. Becoming requires you to be bad at things in public. It requires you to ask questions that reveal exactly what you do not know. The people you admire most did not skip this stage; they simply refused to let it embarrass them out of the room.","source":"Original passage written for practice"},"prompt":"In the final sentence, the phrase \"embarrass them out of the room\" most nearly suggests that","choices":[{"id":"A","text":"embarrassment can drive people to abandon an effort, a pressure the admired people resisted"},{"id":"B","text":"the admired people literally left rooms when they felt embarrassed"},{"id":"C","text":"public speaking is the most difficult part of learning"},{"id":"D","text":"the graduates should avoid situations that might embarrass them"}],"estimatedSeconds":75,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 75, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p3-001', 'ap', 'ap-english-language', 'Claims and Evidence', 'Counterarguments', 'Responding to counterarguments', 'medium', 'mcq', '{"id":"ap-lang-p3-001","exam":"ap","course":"ap-english-language","section":"Claims and Evidence","topic":"Counterarguments","skill":"Responding to counterarguments","difficulty":"medium","type":"mcq","passage":{"title":"Passage 3 (original editorial)","text":"Most of us will never see the Milky Way from our own backyards, and we have largely stopped noticing the loss. Artificial light at night has grown brighter and more widespread for decades, washing out the stars over cities and suburbs alike. Defenders of bright streetlights point to safety, and the concern is real: people deserve to see where they are walking. Yet much outdoor lighting is poorly aimed, spilling sideways into bedrooms and upward into the sky, where it illuminates nothing a pedestrian needs. Shielded fixtures that direct light downward can keep sidewalks visible while restoring some of the darkness overhead. We need not choose between safety and the stars; we need only choose better lamps.","source":"Original passage written for practice"},"prompt":"The writer acknowledges concerns about safety primarily in order to","choices":[{"id":"A","text":"reject the idea that safety matters"},{"id":"B","text":"shift the discussion to the cost of electricity"},{"id":"C","text":"cite expert testimony about crime rates"},{"id":"D","text":"concede a legitimate point before arguing that it does not require current lighting practices"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p3-002', 'ap', 'ap-english-language', 'Claims and Evidence', 'Thesis', 'Identifying the main claim', 'easy', 'mcq', '{"id":"ap-lang-p3-002","exam":"ap","course":"ap-english-language","section":"Claims and Evidence","topic":"Thesis","skill":"Identifying the main claim","difficulty":"easy","type":"mcq","passage":{"title":"Passage 3 (original editorial)","text":"Most of us will never see the Milky Way from our own backyards, and we have largely stopped noticing the loss. Artificial light at night has grown brighter and more widespread for decades, washing out the stars over cities and suburbs alike. Defenders of bright streetlights point to safety, and the concern is real: people deserve to see where they are walking. Yet much outdoor lighting is poorly aimed, spilling sideways into bedrooms and upward into the sky, where it illuminates nothing a pedestrian needs. Shielded fixtures that direct light downward can keep sidewalks visible while restoring some of the darkness overhead. We need not choose between safety and the stars; we need only choose better lamps.","source":"Original passage written for practice"},"prompt":"Which choice best states the writer''s main claim?","choices":[{"id":"A","text":"Streetlights should be removed from residential neighborhoods."},{"id":"B","text":"Better-designed outdoor lighting can maintain safety while reducing light pollution."},{"id":"C","text":"Safety is more important than the ability to see the stars."},{"id":"D","text":"The Milky Way is no longer visible anywhere on Earth."}],"estimatedSeconds":55,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 55, array['rhetoric', 'passage-based']::text[], 1, true),
  ('ap-lang-p3-003', 'ap', 'ap-english-language', 'Style', 'Sentence-level choices', 'Effect of parallel structure', 'medium', 'mcq', '{"id":"ap-lang-p3-003","exam":"ap","course":"ap-english-language","section":"Style","topic":"Sentence-level choices","skill":"Effect of parallel structure","difficulty":"medium","type":"mcq","passage":{"title":"Passage 3 (original editorial)","text":"Most of us will never see the Milky Way from our own backyards, and we have largely stopped noticing the loss. Artificial light at night has grown brighter and more widespread for decades, washing out the stars over cities and suburbs alike. Defenders of bright streetlights point to safety, and the concern is real: people deserve to see where they are walking. Yet much outdoor lighting is poorly aimed, spilling sideways into bedrooms and upward into the sky, where it illuminates nothing a pedestrian needs. Shielded fixtures that direct light downward can keep sidewalks visible while restoring some of the darkness overhead. We need not choose between safety and the stars; we need only choose better lamps.","source":"Original passage written for practice"},"prompt":"The final sentence, \"We need not choose between safety and the stars; we need only choose better lamps,\" primarily serves to","choices":[{"id":"A","text":"present the writer''s solution as simple and the apparent dilemma as a false choice"},{"id":"B","text":"introduce a new counterargument for the reader to consider"},{"id":"C","text":"express the writer''s uncertainty about the proposed solution"},{"id":"D","text":"summarize statistical evidence presented earlier in the passage"}],"estimatedSeconds":70,"tags":["rhetoric","passage-based"],"version":1}'::jsonb, 70, array['rhetoric', 'passage-based']::text[], 1, true),
