  ('ap-csp-u3-002', 'ap', 'ap-computer-science-principles', 'Big Idea 3: Algorithms and Programming', 'Searching', 'Binary search efficiency', 'medium', 'mcq', '{"id":"ap-csp-u3-002","exam":"ap","course":"ap-computer-science-principles","section":"Big Idea 3: Algorithms and Programming","topic":"Searching","skill":"Binary search efficiency","difficulty":"medium","type":"mcq","prompt":"A sorted list contains 1,000 items. What is the maximum number of items a binary search would need to examine to determine whether a particular value is in the list?","choices":[{"id":"A","text":"1,000"},{"id":"B","text":"10"},{"id":"C","text":"500"},{"id":"D","text":"100"}],"estimatedSeconds":55,"tags":["binary search","efficiency"],"version":1}'::jsonb, 55, array['binary search', 'efficiency']::text[], 1, true),
  ('ap-csp-u5-001', 'ap', 'ap-computer-science-principles', 'Big Idea 5: Impact of Computing', 'Safe computing', 'Protecting against phishing', 'easy', 'multi', '{"id":"ap-csp-u5-001","exam":"ap","course":"ap-computer-science-principles","section":"Big Idea 5: Impact of Computing","topic":"Safe computing","skill":"Protecting against phishing","difficulty":"easy","type":"multi","prompt":"Which of the following actions help protect a user against phishing attacks? Select two answers.","choices":[{"id":"A","text":"Reusing the same password on every site so it is easy to remember"},{"id":"B","text":"Checking the sender''s address and previewing a link''s destination before clicking"},{"id":"C","text":"Turning off automatic software updates"},{"id":"D","text":"Enabling multifactor authentication on important accounts"}],"estimatedSeconds":55,"tags":["cybersecurity","select two"],"version":1}'::jsonb, 55, array['cybersecurity', 'select two']::text[], 1, true),
  ('ap-bio-u2-001', 'ap', 'ap-biology', 'Unit 2: Cell Structure and Function', 'Organelles', 'Organelle function', 'easy', 'mcq', '{"id":"ap-bio-u2-001","exam":"ap","course":"ap-biology","section":"Unit 2: Cell Structure and Function","topic":"Organelles","skill":"Organelle function","difficulty":"easy","type":"mcq","prompt":"In eukaryotic cells, the electron transport chain that produces most of the ATP from cellular respiration is located in the","choices":[{"id":"A","text":"inner mitochondrial membrane"},{"id":"B","text":"nucleus"},{"id":"C","text":"rough endoplasmic reticulum"},{"id":"D","text":"Golgi apparatus"}],"estimatedSeconds":55,"tags":["mitochondria","cellular respiration"],"version":1}'::jsonb, 55, array['mitochondria', 'cellular respiration']::text[], 1, true),
  ('ap-bio-u3-001', 'ap', 'ap-biology', 'Unit 3: Cellular Energetics', 'Enzymes', 'Enzyme inhibition', 'medium', 'mcq', '{"id":"ap-bio-u3-001","exam":"ap","course":"ap-biology","section":"Unit 3: Cellular Energetics","topic":"Enzymes","skill":"Enzyme inhibition","difficulty":"medium","type":"mcq","prompt":"The effect of a competitive inhibitor on an enzyme-catalyzed reaction can be reduced by","choices":[{"id":"A","text":"lowering the temperature to near freezing"},{"id":"B","text":"increasing the substrate concentration"},{"id":"C","text":"denaturing the enzyme"},{"id":"D","text":"removing the enzyme''s cofactor"}],"estimatedSeconds":55,"tags":["enzymes","inhibition"],"version":1}'::jsonb, 55, array['enzymes', 'inhibition']::text[], 1, true),
  ('ap-bio-u3-002', 'ap', 'ap-biology', 'Unit 3: Cellular Energetics', 'Photosynthesis', 'Light-dependent reactions', 'medium', 'mcq', '{"id":"ap-bio-u3-002","exam":"ap","course":"ap-biology","section":"Unit 3: Cellular Energetics","topic":"Photosynthesis","skill":"Light-dependent reactions","difficulty":"medium","type":"mcq","prompt":"The oxygen gas released by plants during photosynthesis comes from which molecule?","choices":[{"id":"A","text":"Carbon dioxide"},{"id":"B","text":"Glucose"},{"id":"C","text":"Water"},{"id":"D","text":"ATP"}],"estimatedSeconds":55,"tags":["photosynthesis"],"version":1}'::jsonb, 55, array['photosynthesis']::text[], 1, true),
  ('ap-bio-u5-001', 'ap', 'ap-biology', 'Unit 5: Heredity', 'Mendelian genetics', 'Monohybrid crosses', 'easy', 'numeric', '{"id":"ap-bio-u5-001","exam":"ap","course":"ap-biology","section":"Unit 5: Heredity","topic":"Mendelian genetics","skill":"Monohybrid crosses","difficulty":"easy","type":"numeric","prompt":"Two organisms that are both heterozygous for a single gene ($Aa \\times Aa$) are crossed. What fraction of the offspring are expected to be heterozygous? Enter a fraction or decimal.","hint":"Draw a 2 by 2 Punnett square.","estimatedSeconds":55,"tags":["Punnett square"],"version":1}'::jsonb, 55, array['Punnett square']::text[], 1, true),
  ('ap-bio-u7-001', 'ap', 'ap-biology', 'Unit 7: Natural Selection', 'Population genetics', 'Hardy-Weinberg equilibrium', 'hard', 'numeric', '{"id":"ap-bio-u7-001","exam":"ap","course":"ap-biology","section":"Unit 7: Natural Selection","topic":"Population genetics","skill":"Hardy-Weinberg equilibrium","difficulty":"hard","type":"numeric","prompt":"In a population in Hardy-Weinberg equilibrium, 16% of individuals show a recessive phenotype. What is the expected frequency of heterozygous individuals? Enter a decimal.","hint":"Start from $q^2$, then use $p + q = 1$.","estimatedSeconds":80,"tags":["Hardy-Weinberg"],"version":1}'::jsonb, 80, array['Hardy-Weinberg']::text[], 1, true),
  ('ap-chem-u1-001', 'ap', 'ap-chemistry', 'Unit 1: Atomic Structure and Properties', 'Moles and molar mass', 'Mole calculations', 'easy', 'numeric', '{"id":"ap-chem-u1-001","exam":"ap","course":"ap-chemistry","section":"Unit 1: Atomic Structure and Properties","topic":"Moles and molar mass","skill":"Mole calculations","difficulty":"easy","type":"numeric","prompt":"How many moles of water are in 36.0 grams of $H_2O$? (Molar mass of $H_2O$ = 18.0 g/mol)","estimatedSeconds":55,"tags":["moles"],"version":1}'::jsonb, 55, array['moles']::text[], 1, true),
  ('ap-chem-u1-002', 'ap', 'ap-chemistry', 'Unit 1: Atomic Structure and Properties', 'Periodic trends', 'Ionization energy', 'medium', 'mcq', '{"id":"ap-chem-u1-002","exam":"ap","course":"ap-chemistry","section":"Unit 1: Atomic Structure and Properties","topic":"Periodic trends","skill":"Ionization energy","difficulty":"medium","type":"mcq","prompt":"Which of the following elements has the highest first ionization energy?","choices":[{"id":"A","text":"Lithium"},{"id":"B","text":"Carbon"},{"id":"C","text":"Oxygen"},{"id":"D","text":"Neon"}],"estimatedSeconds":55,"tags":["periodic trends"],"version":1}'::jsonb, 55, array['periodic trends']::text[], 1, true),
  ('ap-chem-u2-001', 'ap', 'ap-chemistry', 'Unit 2: Molecular and Ionic Compound Structure and Properties', 'VSEPR', 'Molecular geometry', 'medium', 'mcq', '{"id":"ap-chem-u2-001","exam":"ap","course":"ap-chemistry","section":"Unit 2: Molecular and Ionic Compound Structure and Properties","topic":"VSEPR","skill":"Molecular geometry","difficulty":"medium","type":"mcq","prompt":"What is the molecular geometry of ammonia, $NH_3$?","choices":[{"id":"A","text":"Trigonal planar"},{"id":"B","text":"Trigonal pyramidal"},{"id":"C","text":"Tetrahedral"},{"id":"D","text":"Bent"}],"estimatedSeconds":55,"tags":["VSEPR"],"version":1}'::jsonb, 55, array['VSEPR']::text[], 1, true),
  ('ap-chem-u8-001', 'ap', 'ap-chemistry', 'Unit 8: Acids and Bases', 'pH', 'Calculating pH of strong acids', 'easy', 'numeric', '{"id":"ap-chem-u8-001","exam":"ap","course":"ap-chemistry","section":"Unit 8: Acids and Bases","topic":"pH","skill":"Calculating pH of strong acids","difficulty":"easy","type":"numeric","prompt":"What is the pH of a 0.0010 M solution of hydrochloric acid, a strong acid?","estimatedSeconds":55,"tags":["pH","strong acids"],"version":1}'::jsonb, 55, array['pH', 'strong acids']::text[], 1, true),
  ('ap-chem-u7-001', 'ap', 'ap-chemistry', 'Unit 7: Equilibrium', 'Le Chatelier''s principle', 'Predicting equilibrium shifts', 'hard', 'mcq', '{"id":"ap-chem-u7-001","exam":"ap","course":"ap-chemistry","section":"Unit 7: Equilibrium","topic":"Le Chatelier''s principle","skill":"Predicting equilibrium shifts","difficulty":"hard","type":"mcq","prompt":"For the exothermic reaction $N_2(g) + 3H_2(g) \\rightleftharpoons 2NH_3(g)$, which change would increase the amount of $NH_3$ present at equilibrium?","choices":[{"id":"A","text":"Adding a catalyst"},{"id":"B","text":"Decreasing the total pressure"},{"id":"C","text":"Decreasing the temperature"},{"id":"D","text":"Removing some $N_2$"}],"estimatedSeconds":70,"tags":["equilibrium","Le Chatelier"],"version":1}'::jsonb, 70, array['equilibrium', 'Le Chatelier']::text[], 1, true),
  ('ap-phys-u1-001', 'ap', 'ap-physics-1', 'Unit 1: Kinematics', 'Constant acceleration', 'Kinematic equations', 'easy', 'numeric', '{"id":"ap-phys-u1-001","exam":"ap","course":"ap-physics-1","section":"Unit 1: Kinematics","topic":"Constant acceleration","skill":"Kinematic equations","difficulty":"easy","type":"numeric","prompt":"A car starts from rest and accelerates uniformly at $3.0 \\text{ m/s}^2$ for $4.0$ seconds. How far, in meters, does the car travel during this time?","hint":"Use $\\Delta x = v_0 t + \\frac{1}{2} a t^2$ with $v_0 = 0$.","estimatedSeconds":55,"tags":["kinematics"],"version":1}'::jsonb, 55, array['kinematics']::text[], 1, true),
  ('ap-phys-u2-001', 'ap', 'ap-physics-1', 'Unit 2: Force and Translational Dynamics', 'Newton''s second law', 'Net force and acceleration', 'easy', 'mcq', '{"id":"ap-phys-u2-001","exam":"ap","course":"ap-physics-1","section":"Unit 2: Force and Translational Dynamics","topic":"Newton''s second law","skill":"Net force and acceleration","difficulty":"easy","type":"mcq","prompt":"A net force of 12 N acts on a 4.0 kg cart on a level track. What is the magnitude of the cart''s acceleration?","choices":[{"id":"A","text":"48 m/s²"},{"id":"B","text":"0.33 m/s²"},{"id":"C","text":"8.0 m/s²"},{"id":"D","text":"3.0 m/s²"}],"estimatedSeconds":55,"tags":["Newton''s laws"],"version":1}'::jsonb, 55, array['Newton''s laws']::text[], 1, true),
  ('ap-phys-u3-001', 'ap', 'ap-physics-1', 'Unit 3: Work, Energy, and Power', 'Conservation of energy', 'Gravitational potential to kinetic energy', 'medium', 'numeric', '{"id":"ap-phys-u3-001","exam":"ap","course":"ap-physics-1","section":"Unit 3: Work, Energy, and Power","topic":"Conservation of energy","skill":"Gravitational potential to kinetic energy","difficulty":"medium","type":"numeric","prompt":"A ball is dropped from rest from a height of 5.0 m. Neglecting air resistance and using $g = 10 \\text{ m/s}^2$, what is the ball''s speed, in m/s, just before it hits the ground?","estimatedSeconds":55,"tags":["energy conservation"],"version":1}'::jsonb, 55, array['energy conservation']::text[], 1, true),
  ('ap-phys-u4-001', 'ap', 'ap-physics-1', 'Unit 4: Linear Momentum', 'Collisions', 'Perfectly inelastic collisions', 'medium', 'mcq', '{"id":"ap-phys-u4-001","exam":"ap","course":"ap-physics-1","section":"Unit 4: Linear Momentum","topic":"Collisions","skill":"Perfectly inelastic collisions","difficulty":"medium","type":"mcq","prompt":"A 2.0 kg cart moving at 3.0 m/s collides with and sticks to a stationary 1.0 kg cart. What is the speed of the carts immediately after the collision?","choices":[{"id":"A","text":"1.0 m/s"},{"id":"B","text":"2.0 m/s"},{"id":"C","text":"3.0 m/s"},{"id":"D","text":"6.0 m/s"}],"estimatedSeconds":55,"tags":["momentum"],"version":1}'::jsonb, 55, array['momentum']::text[], 1, true),
  ('ap-phys-u2-002', 'ap', 'ap-physics-1', 'Unit 2: Force and Translational Dynamics', 'Circular motion', 'Centripetal force', 'easy', 'mcq', '{"id":"ap-phys-u2-002","exam":"ap","course":"ap-physics-1","section":"Unit 2: Force and Translational Dynamics","topic":"Circular motion","skill":"Centripetal force","difficulty":"easy","type":"mcq","prompt":"An object moves in a horizontal circle at constant speed. What is the direction of the net force on the object?","choices":[{"id":"A","text":"Tangent to the circle, in the direction of motion"},{"id":"B","text":"Directly away from the center of the circle"},{"id":"C","text":"Toward the center of the circle"},{"id":"D","text":"There is no net force because the speed is constant"}],"estimatedSeconds":55,"tags":["circular motion"],"version":1}'::jsonb, 55, array['circular motion']::text[], 1, true)
insert into public.question_keys (question_id, correct, tolerance, explanation) values
  ('sat-math-alg-001', '["C"]'::jsonb, null, 'Subtract 7 from both sides to get $3x = 18$, so $x = 6$. Then $6x - 4 = 6(6) - 4 = 32$. Choice D is the value of $6x$ alone, and choice A comes from stopping after finding $3x - 4$.'),
  ('sat-math-alg-002', '["-1"]'::jsonb, null, 'The slope is $\frac{17 - 5}{6 - 2} = \frac{12}{4} = 3$. Using $y = 3x + b$ with the point $(2, 5)$: $5 = 3(2) + b$, so $b = -1$. The line crosses the $y$-axis at $(0, -1)$.'),
  ('sat-math-alg-003', '["B"]'::jsonb, null, 'Adding the equations eliminates $y$: $3x = 12$, so $x = 4$. Substituting into $x - y = 1$ gives $y = 3$. Therefore $xy = 4 \cdot 3 = 12$. Choice A is $x + y$, not $xy$.'),
  ('sat-math-alg-004', '["A"]'::jsonb, null, 'A linear system has no solution when the lines are parallel but distinct: same slope, different intercepts. The coefficients must be proportional, so $\frac{k}{4} = \frac{3}{6}$, giving $k = 2$. Check: with $k = 2$, doubling the first equation gives $4x + 6y = 24$, which has the same left side as $4x + 6y = 9$ but a different constant, so the lines never meet. Choice D comes from setting $\frac{k}{4} = \frac{6}{3}$, which flips the ratio.'),
  ('sat-math-alg-005', '["D"]'::jsonb, null, 'The total cost is the fixed fee plus the monthly charge times the number of months: $40 + 25m$. "At most" means less than or equal to, so $40 + 25m \le 340$. Choice A swaps the fee and the rate, choice B reverses the inequality, and choice C wrongly charges the sign-up fee every month.'),
  ('sat-math-adv-001', '["C"]'::jsonb, null, 'Expand each square: $(x+5)^2 = x^2 + 10x + 25$ and $(x-5)^2 = x^2 - 10x + 25$. Subtracting gives $20x$. You can also use the difference of squares: $(a + b)(a - b)$ with $a = x+5$ and $b = x-5$ gives $(2x)(10) = 20x$. Choice D comes from treating $(x+5)^2$ as $x^2 + 25$.'),
  ('sat-math-adv-002', '["2"]'::jsonb, null, 'Factor the quadratic: $x^2 - 8x + 15 = (x - 3)(x - 5)$, so the solutions are $x = 3$ and $x = 5$. Their positive difference is $5 - 3 = 2$.'),
  ('sat-math-adv-003', '["D"]'::jsonb, null, 'Use $f(5) = 14$ to find $a$: $a(5-3)^2 + 2 = 14$, so $4a = 12$ and $a = 3$. Then $f(0) = 3(0 - 3)^2 + 2 = 3(9) + 2 = 29$. Choice A forgets to add the 2 at the end, choice B ignores the $+2$ when solving for $a$ (giving $a = 3.5$), and choice C treats $(5-3)^2$ as $2$ instead of $4$ (giving $a = 6$).'),
  ('sat-math-adv-004', '["B"]'::jsonb, null, 'Doubling means the growth factor is 2. The number of doublings after $t$ hours is $\frac{t}{3}$, so $P(t) = 500(2)^{t/3}$. Check: at $t = 3$, $P = 1000$. Choice A doubles three times every hour, choice C swaps the factor and period, and choice D adds instead of multiplying.'),
  ('sat-math-adv-005', '["7"]'::jsonb, null, 'Factor the numerator: $x^2 - 9 = (x - 3)(x + 3)$. For $x \ne 3$, the expression simplifies to $x + 3$. Setting $x + 3 = 10$ gives $x = 7$. The value $x = 3$ is excluded because it makes the denominator zero.'),
  ('sat-math-psd-001', '["B"]'::jsonb, null, 'The car gets $\frac{168}{6} = 28$ miles per gallon. Traveling 252 miles requires $\frac{252}{28} = 9$ gallons.'),
  ('sat-math-psd-002', '["80"]'::jsonb, null, 'After a $25\%$ increase the price is $80 \times 1.25 = 100$. A $20\%$ decrease from $100$ gives $100 \times 0.80 = 80$. The final price is $\$80$. The changes do not simply combine to a $5\%$ increase because the second percentage applies to a different base.'),
  ('sat-math-psd-003', '["D"]'::jsonb, null, 'The condition "in the debate club" restricts the group to the 40 debate students. Of those, 28 are in grade 11, so the probability is $\frac{28}{40} = \frac{7}{10}$. Choice A divides by all 80 students, and choice B divides by all 50 grade 11 students.'),
  ('sat-math-psd-004', '["B"]'::jsonb, null, 'From 1 hour to 8 hours, scores rise from about 52 to about 79, an increase of about 27 points over 7 hours, or roughly $\frac{27}{7} \approx 3.9$ points per hour. (A least-squares fit gives a slope of about 3.86.) Choice A is the reciprocal of the slope, and choice D is close to the first score, not a rate.'),
  ('sat-math-geo-001', '["C"]'::jsonb, null, 'The hypotenuse is $AB = \sqrt{9^2 + 12^2} = \sqrt{225} = 15$. The side opposite angle $A$ is $BC = 12$, so $\sin A = \frac{12}{15} = \frac{4}{5}$. Choice A is $\cos A$, and choice D is $\tan A$.'),
  ('sat-math-geo-002', '["5"]'::jsonb, null, 'Complete the square in each variable: $x^2 - 6x + 9 + y^2 + 8y + 16 = 9 + 16$, which gives $(x - 3)^2 + (y + 4)^2 = 25$. A circle $(x-h)^2 + (y-k)^2 = r^2$ has radius $r = \sqrt{25} = 5$.'),
  ('sat-math-geo-003', '["C"]'::jsonb, null, 'Volume equals length times width times height, so $168 = 6 \cdot 4 \cdot h = 24h$. Dividing gives $h = 7$ centimeters.'),
  ('sat-math-geo-004', '["D"]'::jsonb, null, 'The angles of a triangle sum to $180^\circ$: $x + 2x + 3x - 30 = 180$, so $6x = 210$ and $x = 35$. The angles are $35^\circ$, $70^\circ$, and $3(35) - 30 = 75^\circ$. The largest is $75^\circ$. Choice A is $x$ itself, and choice C is $3x$ without subtracting 30.'),
  ('sat-rw-wic-001', '["A"]'::jsonb, null, 'The colon introduces evidence that different branches recovered at very different rates, from months, to years, to never. That contrast shows the recovery was not "uniform," meaning consistent throughout. Nothing in the text discusses speed overall (sudden), visibility (invisible), or whether the recovery would last (permanent).'),
  ('sat-rw-wic-002', '["C"]'::jsonb, null, 'The second clause shows that even normally harsh critics praised the novelist, so the praise was generous and wholehearted. "Unstinting" means given freely and without holding back. "Tepid" (lukewarm) and "ambivalent" (mixed) contradict the strong praise, and nothing suggests the praise came too early (premature).'),
  ('sat-rw-wic-003', '["B"]'::jsonb, null, 'The text says the walls had no new cracks after the storm, so the lighthouse stayed whole and undamaged, which is what "intact" means. "Fragile" contradicts the evidence, and the text gives no information about whether the lighthouse was abandoned or lit.'),
  ('sat-rw-tsp-001', '["D"]'::jsonb, null, 'The text first describes a problem (treeless neighborhoods are hotter), then a response (Fairhaven planted 12,000 trees on the hottest blocks), and finally early, qualified results (those blocks have cooled more). No competing theories or debate are presented, and the focus is on a recent program rather than a historical event.'),
  ('sat-rw-ctc-001', '["B"]'::jsonb, null, 'Text 2 presents limb-bone structure and trackways on firm ground as evidence that sauropods lived mainly on land, which directly challenges Text 1''s assumption that they lived in water. Text 2 does not agree with the assumption, discuss sauropod size, or distinguish young from adult animals.'),
  ('sat-rw-cid-001', '["C"]'::jsonb, null, 'The text describes the birds'' caching behavior and then an experiment showing that moving landmarks shifted where the birds searched, leading to the conclusion that they use spatial memory tied to landmarks. The experiment actually suggests smell is not the main cue, and the text says nothing about hiding seeds from other animals or comparing the number of seeds with other birds.'),
  ('sat-rw-coe-001', '["D"]'::jsonb, null, 'The claim compares the two watering methods across seasons, so the support must show that the difference between methods was largest in summer. Choice D computes each season''s gap (1.7, 0.3, and 0.1 kilograms) and shows summer''s is greatest. Choice A compares seasons for only one method, and choices B and C do not compare the methods'' advantage at all.'),
  ('sat-rw-coe-002', '["B"]'::jsonb, null, 'Choice B shows Mara repeating the same action at the same time every evening, and it links that ritual to her relaxing ("her shoulders loosen"), which illustrates comfort in routine. The other quotations describe a dream, a town debate, and her brother''s departure, none of which connect routine to comfort.'),
  ('sat-rw-inf-001', '["D"]'::jsonb, null, 'The clay came from at least 200 kilometers away, yet the decoration matches the settlement''s own style, so the most reasonable inference is that local potters used imported clay. Choice A contradicts the matching designs, choice B adds a claim about clay quality the text never makes, and choice C conflicts with the evidence that pottery was produced at the site.'),
  ('sat-rw-bnd-001', '["C"]'::jsonb, null, 'Both parts of the sentence are independent clauses ("Botanist Ynés Mexía did not begin..." and "over the following thirteen years, she gathered..."). A semicolon can join two independent clauses. No punctuation (choice A) creates a run-on, a comma alone (choice B) creates a comma splice, and "which" (choice D) produces an ungrammatical clause.'),
  ('sat-rw-fss-001', '["B"]'::jsonb, null, 'The subject of the sentence is the singular noun "collection," not "letters," which is part of the prepositional phrase "of letters." A singular subject takes the singular verb "is." The other choices are plural verbs.'),
  ('sat-rw-fss-002', '["C"]'::jsonb, null, 'The pronoun refers back to "the city council," a singular collective noun, and it needs to show possession (the council''s members). The singular possessive pronoun is "its." "It''s" means "it is," "they''re" means "they are," and "their" is plural, which does not agree with the singular antecedent.'),
  ('sat-rw-trn-001', '["D"]'::jsonb, null, 'The second sentence adds a further, related fact about the frogs'' transparency, so an additive transition such as "Moreover" fits. The sentences do not contrast (In contrast, Nevertheless), and the first fact does not cause the second (Therefore).'),
  ('sat-rw-trn-002', '["A"]'::jsonb, null, 'Because a mirror reflects all colors at the same angle, the reflecting telescope avoided color fringes. The final sentence is a consequence of the previous one, so "As a result" is the logical transition. The sentence is not an example, a contrast, or a parallel case.'),
  ('sat-rw-syn-001', '["C"]'::jsonb, null, 'The goal is to explain the vault''s purpose. Choice C identifies the vault, says what it stores, and explains why: to protect crop diversity if other samples are lost. Choices A and D give only location and opening date, and choice B never mentions the vault.'),
  ('ap-stats-u1-001', '["B"]'::jsonb, null, 'In a right-skewed distribution, a small number of very large values pull the mean toward the long right tail, while the median is resistant to extreme values. As a result, the mean is typically greater than the median.'),
  ('ap-stats-u1-002', '["1.75"]'::jsonb, 0.001, 'A $z$-score measures how many standard deviations a value is from the mean: $z = \frac{86 - 72}{8} = \frac{14}{8} = 1.75$. The student scored 1.75 standard deviations above the mean.'),
  ('ap-stats-u2-001', '["C"]'::jsonb, null, 'A correlation of $-0.85$ indicates a strong negative linear relationship: older cars tend to have lower prices. Choice A confuses $r$ with $r^2$ (here $r^2 \approx 0.72$). Correlation alone does not establish causation (choice B), and the slope equals $r \cdot \frac{s_y}{s_x}$, which is not generally equal to $r$ (choice D).'),
  ('ap-stats-u2-002', '["3"]'::jsonb, null, 'The predicted value is $\hat{y} = 12 + 3.5(4) = 26$. The residual is observed minus predicted: $29 - 26 = 3$. A positive residual means the point lies above the regression line.'),
  ('ap-stats-u3-001', '["B"]'::jsonb, null, 'Random assignment balances the effects of other variables (soil quality, sunlight, drainage) across treatment groups on average, which allows cause-and-effect conclusions about the treatments. Generalizing to a larger population (choice A) requires random sampling, not random assignment. Group sizes can be fixed without randomization.'),
  ('ap-stats-u3-002', '["A"]'::jsonb, null, 'Callers chose themselves to participate, and people with strong opinions (often negative ones) are more likely to call in. That self-selection is voluntary response bias, so the 78% figure likely overstates opposition in the population.'),
  ('ap-stats-u4-001', '["0.7"]'::jsonb, 0.001, 'Because the events are independent, $P(A \text{ and } B) = 0.4 \times 0.5 = 0.2$. By the general addition rule, $P(A \text{ or } B) = 0.4 + 0.5 - 0.2 = 0.7$.'),
  ('ap-stats-u5-001', '["C"]'::jsonb, null, 'The standard deviation of $\bar{x}$ is $\frac{\sigma}{\sqrt{n}}$. Multiplying $n$ by 4 multiplies $\sqrt{n}$ by 2, which divides the standard deviation by 2. Choice B forgets the square root.'),
  ('ap-stats-u6-001', '["D"]'::jsonb, null, 'The confidence level describes the method: about 95% of intervals built this way capture the true parameter. So we are 95% confident this particular interval captures the true proportion. Once computed, a specific interval either contains the parameter or does not, so choice A misstates it. Choice B is about sample proportions, not the parameter, and choice C misreads what the interval measures.'),
  ('ap-stats-u7-001', '["B"]'::jsonb, null, 'A $p$-value is computed assuming the null hypothesis is true. It is the probability of getting a result at least as extreme as the observed one under that assumption. It is not the probability that either hypothesis is true (choices A and C), and it says nothing about the size of the difference (choice D).'),
  ('apes-u1-001', '["C"]'::jsonb, null, 'As a rule of thumb, about 10% of the energy at one trophic level is transferred to the next. Most of the rest is lost as heat through cellular respiration or is never consumed. Choice D is roughly the share that is lost, not transferred.'),
  ('apes-u1-002', '["B"]'::jsonb, null, 'Nitrogen fixation, performed by certain bacteria (such as those in legume root nodules) and by lightning or industrial processes, converts $N_2$ into ammonia. Nitrification converts ammonia to nitrites and nitrates, denitrification returns nitrogen to the atmosphere as $N_2$, and ammonification releases ammonia from decomposing organic matter.'),
  ('apes-u3-001', '["35"]'::jsonb, 0.5, 'The rule of 70 estimates doubling time as $\frac{70}{\text{percent growth rate}}$. Here, $\frac{70}{2} = 35$ years.'),
  ('apes-u3-002', '["D"]'::jsonb, null, 'K-selected species, such as elephants and whales, invest heavily in a small number of offspring and tend to maintain populations near the environment''s carrying capacity. Choices A, B, and C describe r-selected species, which produce many offspring and experience boom-and-bust population cycles.'),
  ('apes-u4-001', '["A"]'::jsonb, null, 'Most atmospheric ozone is concentrated in the stratosphere, roughly 15 to 35 kilometers above Earth''s surface, where it absorbs UV-B radiation. Ozone in the troposphere, near the ground, is a harmful pollutant rather than a protective layer.'),
  ('apes-u5-001', '["C"]'::jsonb, null, 'Contour plowing creates furrows that follow the land''s elevation lines, slowing water runoff and trapping soil on slopes. Removing windbreaks and leaving fields bare increase erosion, and monocropping can degrade soil over time.'),
  ('apes-u6-001', '["D"]'::jsonb, null, 'Each kWh switched from coal to wind saves about $820 - 11 = 809$ grams of $CO_2$-equivalent. For 1,000 kWh that is $809{,}000$ grams, or 809 kilograms. Choices A and C are off by a factor of 10, and choice B uses the natural gas value.'),
  ('apes-u7-001', '["B"]'::jsonb, null, 'Ground-level ozone is a secondary pollutant. It forms when nitrogen oxides (mainly from vehicle exhaust and power plants) and volatile organic compounds react in sunlight, which is why ozone levels typically peak on sunny afternoons.'),
  ('apes-u8-001', '["C"]'::jsonb, null, 'Excess nitrogen and phosphorus fuel an algal bloom. When the algae die, aerobic bacteria decompose them and use up dissolved oxygen, creating hypoxic conditions in which fish cannot survive. This sequence is called eutrophication.'),
  ('apes-u9-001', '["A"]'::jsonb, null, 'When the ocean absorbs $CO_2$, it forms carbonic acid, which lowers pH and reduces the concentration of carbonate ions. Corals, oysters, and other calcifying organisms need carbonate ions to build calcium carbonate shells and skeletons, so acidification makes calcification harder.'),
  ('apush-p2-001', '["C"]'::jsonb, null, 'Improving economic conditions in England reduced the supply of indentured servants, and Bacon''s Rebellion (1676) showed planters the dangers of a large population of landless former servants. Both pushed Chesapeake planters toward enslaved African labor. The cotton gin (1793) and the 1808 ban on importing enslaved people came much later, and the Great Awakening was a religious movement.'),
  ('apush-p3-001', '["B"]'::jsonb, null, 'Shays'' Rebellion (1786-1787), an uprising of indebted Massachusetts farmers, showed that the Confederation Congress could not raise an army or restore order, which alarmed many leaders and helped lead to the Constitutional Convention of 1787. The Whiskey Rebellion (1794) occurred under the Constitution, the Stamp Act Congress (1765) predated independence, and the Nullification Crisis came in the 1830s.'),
  ('apush-p4-001', '["A"]'::jsonb, null, 'The Erie Canal made it cheap to ship Midwestern grain east and manufactured goods west, binding the Northeast and the Old Northwest into an interconnected market and helping make New York City the nation''s leading port. Steamboats continued to operate, and the canal pulled Midwestern trade toward the Northeast rather than the South.'),
  ('apush-p5-001', '["C"]'::jsonb, null, 'The Fugitive Slave Act forced many Northerners to confront slavery directly, and several northern states passed personal liberty laws to obstruct it, while support for the Underground Railroad and abolitionism grew. Southern secession did not begin until 1860, the Republican Party was founded in 1854 and grew rather than collapsed, and no national agreement ended slavery''s expansion.'),
  ('apush-p6-001', '["D"]'::jsonb, null, 'Responding to farmers'' complaints about discriminatory railroad rates, Congress passed the Interstate Commerce Act to regulate railroads and created the Interstate Commerce Commission, the first federal regulatory agency. Standard Oil was broken up in 1911 under the Sherman Antitrust Act, the federal income tax came with the Sixteenth Amendment (1913), and Chinese immigration was restricted by the Chinese Exclusion Act (1882).'),
  ('apush-p7-001', '["B"]'::jsonb, null, 'Public outrage over The Jungle helped push Congress to pass the Meat Inspection Act and the Pure Food and Drug Act in 1906, examples of Progressive Era consumer protection. The Sherman Act (1890) predated the novel, and the Nineteenth Amendment (1920) and the Federal Reserve Act (1913) addressed suffrage and banking.'),
  ('apush-p7-002', '["C"]'::jsonb, null, 'The Social Security Act represented a major expansion of the federal government''s responsibility for citizens'' economic well-being, a hallmark of the New Deal. It moved away from 1920s laissez-faire approaches and from reliance on private charity, and New Deal programs increased rather than reduced federal spending.'),
  ('apush-p8-001', '["A"]'::jsonb, null, 'The Marshall Plan provided billions of dollars in economic aid to help Western Europe recover after World War II, reflecting the containment strategy''s belief that economic stability would limit communism''s appeal. NATO (1949) was the military alliance, and the Korean War began in 1950.'),
  ('apush-p8-002', '["D"]'::jsonb, null, 'Brown v. Board of Education held that segregated public schools are inherently unequal and violate the Fourteenth Amendment''s Equal Protection Clause, overturning Plessy v. Ferguson''s "separate but equal" doctrine in public education. Court-ordered busing was addressed in Swann v. Charlotte-Mecklenburg (1971), and Miranda rights came from Miranda v. Arizona (1966).'),
  ('apush-p9-001', '["C"]'::jsonb, null, 'The Reagan administration cut income tax rates, pursued deregulation, and sought to limit the growth of federal social programs, reflecting the conservative movement''s emphasis on smaller government and free markets. The Great Society and Civil Rights Act date to the 1960s, and the EPA was created in 1970.'),
  ('ap-lang-p1-001', '["B"]'::jsonb, null, 'The writer concedes that fewer people borrow books, then uses observed examples to argue that the library''s value lies in the help it provides, not just in lending books. The passage does not criticize residents, recount history, or propose a funding plan.'),
  ('ap-lang-p1-002', '["C"]'::jsonb, null, 'The writer counts visitors and then describes specific people using the library''s services, which directly undercuts the claim that the building is "supposedly obsolete." The examples are anecdotal rather than statistical, and they do not discuss the collection or hours.'),
  ('ap-lang-p1-003', '["D"]'::jsonb, null, 'The sentence balances two parallel clauses with opposite quantifiers ("None" and "all") and contrasting objects ("a book" and "the library"). This antithesis sharpens the writer''s distinction between the library as a book lender and the library as a place of help. No authority is cited, and the statement is not exaggerated or metaphorical.'),
  ('ap-lang-p2-001', '["A"]'::jsonb, null, 'Opening by challenging a cliché graduates have heard many times ("you can be anything") is surprising, which captures attention, and the speaker frames it as telling "the truth," establishing candor. The speaker does not blame teachers, sustain humor, or discuss credentials.'),
  ('ap-lang-p2-002', '["C"]'::jsonb, null, 'The speaker replaces the idea of instantly "being" anything with "becoming," which is "slower" and requires being "bad at things in public." The distinction reframes success as a process that includes failure. The speaker praises, rather than dismisses, admired people and never argues against ambition.'),
  ('ap-lang-p2-003', '["A"]'::jsonb, null, 'The phrase figuratively presents embarrassment as a force that can push people to quit. The speaker says admired people "refused to let it" do so, meaning they persisted despite awkwardness. The phrase is not literal, and the speech encourages, rather than discourages, risking embarrassment.'),
  ('ap-lang-p3-001', '["D"]'::jsonb, null, 'The writer grants that "the concern is real" and then argues that poorly aimed lights do not serve pedestrians, so better fixtures can preserve safety and darkness. This is a concession followed by a rebuttal. The writer does not dismiss safety, discuss cost, or cite experts.'),
  ('ap-lang-p3-002', '["B"]'::jsonb, null, 'The writer argues that shielded, downward-facing fixtures can keep sidewalks visible while restoring the night sky, culminating in "we need only choose better lamps." The writer never calls for removing streetlights, does not rank safety above the stars, and says the Milky Way is hard to see from backyards, not invisible everywhere.'),
  ('ap-lang-p3-003', '["A"]'::jsonb, null, 'The parallel phrasing ("need not choose ... need only choose") contrasts a supposed either-or dilemma with a single practical step, framing the trade-off as false and the solution as easy. The sentence is a confident conclusion rather than a new counterargument or a hedge, and the passage contains no statistics.'),
  ('ap-csp-u2-001', '["45"]'::jsonb, null, 'Each binary digit represents a power of 2. From left to right, $101101_2 = 1(32) + 0(16) + 1(8) + 1(4) + 0(2) + 1(1) = 32 + 8 + 4 + 1 = 45$.'),
  ('ap-csp-u2-002', '["A","C"]'::jsonb, null, 'Lossless compression allows perfect reconstruction of the original data, which is essential for text, source code, and other files where any change would corrupt the content. Lossy compression usually achieves smaller files (so B is false) by discarding details people are unlikely to notice, which describes lossy rather than lossless compression (D).'),
  ('ap-csp-u4-001', '["B"]'::jsonb, null, 'DNS works like a directory: when you type a domain name, DNS servers return the numeric IP address that devices use to route requests. Encryption is handled by protocols such as TLS, packets are created by protocols such as TCP/IP, and MAC addresses are built into hardware.'),
  ('ap-csp-u3-001', '["15"]'::jsonb, null, 'Trace each iteration. Start: $x = 3, y = 5$. After iteration 1: $x = 8, y = 4$. After iteration 2: $x = 12, y = 3$. After iteration 3: $x = 15, y = 2$. The code displays 15.'),
  ('ap-csp-u3-002', '["B"]'::jsonb, null, 'Binary search halves the remaining search range with each comparison. Because $2^{10} = 1024 \ge 1000$, at most 10 comparisons are needed. Examining all 1,000 items would be a linear search, and 500 is the average for a linear search.'),
  ('ap-csp-u5-001', '["B","D"]'::jsonb, null, 'Inspecting senders and link destinations helps users spot fake messages, and multifactor authentication limits the damage if a password is stolen, because an attacker would also need the second factor. Reusing passwords and disabling updates increase risk.'),
  ('ap-bio-u2-001', '["A"]'::jsonb, null, 'The electron transport chain and ATP synthase are embedded in the inner mitochondrial membrane, where a proton gradient drives most ATP production during aerobic respiration. The nucleus stores DNA, the rough ER synthesizes proteins, and the Golgi modifies and packages them.'),
  ('ap-bio-u3-001', '["B"]'::jsonb, null, 'A competitive inhibitor binds the enzyme''s active site and competes with the substrate. Adding more substrate makes it more likely that substrate, rather than inhibitor, occupies the active site, so the reaction rate can approach its maximum. Lowering temperature, denaturing the enzyme, or removing a cofactor would further reduce activity.'),
  ('ap-bio-u3-002', '["C"]'::jsonb, null, 'In the light-dependent reactions, photosystem II splits water molecules to replace electrons, releasing $O_2$ as a byproduct. Isotope-labeling experiments confirmed that the oxygen comes from water, not carbon dioxide, which supplies carbon for sugars in the Calvin cycle.'),
  ('ap-bio-u5-001', '["1/2","0.5"]'::jsonb, null, 'A Punnett square for $Aa \times Aa$ gives $AA$, $Aa$, $aA$, and $aa$ in equal proportions. Two of the four outcomes are heterozygous, so the expected fraction is $\frac{2}{4} = \frac{1}{2}$, or 0.5.'),
  ('ap-bio-u7-001', '["0.48"]'::jsonb, 0.001, 'The recessive phenotype frequency is $q^2 = 0.16$, so $q = 0.4$ and $p = 1 - 0.4 = 0.6$. Heterozygotes occur at frequency $2pq = 2(0.6)(0.4) = 0.48$.'),
  ('ap-chem-u1-001', '["2","2.0","2.00"]'::jsonb, 0.01, 'Divide mass by molar mass: $\frac{36.0 \text{ g}}{18.0 \text{ g/mol}} = 2.00 \text{ mol}$.'),
  ('ap-chem-u1-002', '["D"]'::jsonb, null, 'First ionization energy generally increases across a period because effective nuclear charge increases while electrons stay in the same shell. Neon, a noble gas at the end of period 2, has a filled valence shell and the highest first ionization energy of these elements.'),
  ('ap-chem-u2-001', '["B"]'::jsonb, null, 'Nitrogen in $NH_3$ has four electron domains: three bonding pairs and one lone pair. The electron-domain geometry is tetrahedral, but the lone pair is not counted in the molecular shape, which is trigonal pyramidal with bond angles of about 107 degrees.'),
  ('ap-chem-u8-001', '["3"]'::jsonb, 0.01, 'HCl dissociates completely, so $[H^+] = 1.0 \times 10^{-3}$ M. Then $\text{pH} = -\log(1.0 \times 10^{-3}) = 3$.'),
  ('ap-chem-u7-001', '["C"]'::jsonb, null, 'Because the forward reaction releases heat, lowering the temperature shifts the equilibrium toward products, increasing $NH_3$. A catalyst speeds up reaching equilibrium without shifting it, lowering pressure favors the side with more gas moles (the reactants, 4 moles vs. 2), and removing $N_2$ shifts the equilibrium toward reactants.'),
  ('ap-phys-u1-001', '["24"]'::jsonb, 0.01, 'With an initial velocity of zero, $\Delta x = \frac{1}{2}at^2 = \frac{1}{2}(3.0)(4.0)^2 = 24$ meters.'),
  ('ap-phys-u2-001', '["D"]'::jsonb, null, 'Newton''s second law gives $a = \frac{F_{net}}{m} = \frac{12 \text{ N}}{4.0 \text{ kg}} = 3.0 \text{ m/s}^2$. Choice A multiplies instead of dividing, and choice B inverts the ratio.'),
  ('ap-phys-u3-001', '["10"]'::jsonb, 0.05, 'Setting $mgh = \frac{1}{2}mv^2$ gives $v = \sqrt{2gh} = \sqrt{2(10)(5.0)} = \sqrt{100} = 10$ m/s. The mass cancels.'),
  ('ap-phys-u4-001', '["B"]'::jsonb, null, 'Momentum is conserved: $(2.0)(3.0) + (1.0)(0) = (3.0)v_f$, so $v_f = \frac{6.0}{3.0} = 2.0$ m/s. Choice D is the total momentum in kg·m/s, not a speed.'),
  ('ap-phys-u2-002', '["C"]'::jsonb, null, 'Even at constant speed, the velocity''s direction changes continuously, so the object accelerates toward the center (centripetal acceleration). By Newton''s second law, the net force also points toward the center. Constant speed does not mean constant velocity.')
